select case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end launch_cohort, category, brand, count(case when category = 'Electronics' then 1 end) electronics_count from products where cost < 210 group by case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end, category, brand order by brand, launch_cohort, category limit 10;
